using System;
using Faolan.Core.Enums;
using Faolan.Core.Extensions;
using Faolan.Core.Network.Constants;

namespace Faolan.Core.Network.Codecs.Combat
{
	// NewLevelIIR (0x6D314743) - the LEVEL-UP EVENT the client processes to draw the "Congratulations, you have
	// reached level N!" center-screen banner and play the level-up visual/audio effect. The banner TEXT is client-side:
	// it appears in NO capture (grep `Congratulations`/`reached level` on the combat-levelup trace = 0 hits), so it is
	// generated by the client's own level-up handler, gated on THIS packet. Sending only the Level stat + the
	// AttributeChanged feedback lines (as the pre-#209 path did) does not fire it.
	//
	// Carried as an IIR on the WORLD conversation. Wire grammar (big-endian), decoded 2026-07-02 from the
	// combat-levelup capture (Blablabla_soldier-guardian..., frame 9937 - the L1->L2 ding):
	//   [u32 0x6D314743]   NewLevelIIR sub-opcode
	//   [u32 0x0000C350]   Character marker
	//   [u32 instance]     the target GameInterface object (= the receiver endpoint instance / ClientInstance)
	//   [u8  0x00]         lead/env flag (constant 0 in the capture)
	//   [u32 newLevel]     the level just reached (2 in the capture -> "reached level 2")
	//   [u32 x6]           the XP summary, DECODED (#297): [Exp, ExpCurrentLevelBase, MaxExp, 1, 8, 0] - the same
	//                      cumulative triple the stat sheet carries, for the level just reached, then three
	//                      constants. Proven across the 14 dings in the corpus: the first word is the player's own
	//                      running total and varies (the L2 ding reads 100 / 120 / 168 across seven captures) while
	//                      the two thresholds behind it never do (100 and 340 at every L2 ding, 340/740 at every L3,
	//                      ...). Gated by LevelingCurveCorpusTests.
	//
	// The u32 carrier length belongs to the SENDER (#530 rule 2).
	public static class NewLevelCodec
	{
		public const int DeltaCount = 6;
		public const uint Opcode = (uint)IirTypes.NewLevelIIR;
		private const byte LeadFlag = 0x00;

		// CANONICAL - the only method here that writes bytes.
		public static byte[] Build(NewLevelIIR value)
		{
			ArgumentNullException.ThrowIfNull(value);
			using var s = new FaolanStream();
			Write(s, value);
			return s.ToArray();
		}

		// `deltas` is padded/truncated to 6; the live path passes none (an all-zero summary).
		public static byte[] Build(uint instance, uint newLevel, ReadOnlySpan<uint> deltas = default)
		{
			var d = new uint[DeltaCount];
			for (var i = 0; i < DeltaCount && i < deltas.Length; i++)
				d[i] = deltas[i];

			return Build(new NewLevelIIR(instance, LeadFlag, newLevel, d));
		}

		public static NewLevelIIR Parse(in ReadOnlySpan<byte> data)
		{
			var r = new SpanReader(data, nameof(NewLevelCodec));
			var value = Read(ref r);
			r.EnsureAtEnd();
			return value;
		}

		internal static NewLevelIIR Read(ref SpanReader r)
		{
			r.ExpectU32Be(Opcode, "NewLevelIIR subop");
			r.ExpectU32Be(EntityClass.Character, "entity class");
			var instance = r.ReadU32Be();
			var env = r.ReadU8();
			var newLevel = r.ReadU32Be();

			var deltas = new uint[DeltaCount];
			for (var i = 0; i < DeltaCount; i++)
				deltas[i] = r.ReadU32Be();

			return new NewLevelIIR(instance, env, newLevel, deltas);
		}

		internal static void Write(FaolanStream s, NewLevelIIR v)
		{
			s.WriteUInt32(Opcode).WriteUInt32(EntityClass.Character).WriteUInt32(v.Instance).WriteByte(v.Env).WriteUInt32(v.NewLevel);
			for (var i = 0; i < DeltaCount; i++)
			{
				s.WriteUInt32(i < v.Deltas.Length
					? v.Deltas[i]
					: 0u);
			}
		}
	}

	// NewLevelIIR (0x6D314743). `Deltas` is always six words.
	public sealed record NewLevelIIR(uint Instance, byte Env, uint NewLevel, uint[] Deltas);
}
